const queries = [
  { query: 'مسلسل تركي مدبلج بالعربية الحلقة 1',     origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'مسلسل هندي مدبلج بالعربية الحلقة 1',     origin: 'indian',   language: 'ar_dubbed' },
  { query: 'مسلسل كوري مدبلج بالعربية الحلقة 1',     origin: 'korean',   language: 'ar_dubbed' },
  { query: 'مسلسل صيني مدبلج بالعربية الحلقة 1',     origin: 'chinese',  language: 'ar_dubbed' },
  { query: 'مسلسل مغربي بالدارجة الحلقة الأولى',     origin: 'moroccan', language: 'darija'    },
  { query: 'مسلسل تركي رومانسي مدبلج حلقة 1 2024',   origin: 'turkish',  language: 'ar_dubbed' },
  { query: 'مسلسل هندي دراما مدبلج عربي الحلقة 1',   origin: 'indian',   language: 'ar_dubbed' },
  { query: 'مسلسل كوري رومانسي مدبلج عربي حلقة 1',  origin: 'korean',   language: 'ar_dubbed' }
];
return queries.map(q => ({ json: q }));

const results = $input.first().json.results || [];
const query = $('Generate Queries').item.json;

function extractSeriesName(title) {
  return title
    .replace(/الحلقة\s*\d+/g, '')
    .replace(/حلقة\s*\d+/g, '')
    .replace(/episode\s*\d+/gi, '')
    .replace(/ep\.?\s*\d+/gi, '')
    .replace(/\s*[-|].*$/, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

function extractEpisodeNumber(title) {
  const m = title.match(/(?:الحلقة|حلقة|ep\.?|episode)\s*(\d+)/i);
  return m ? parseInt(m[1]) : 1;
}

const series = results
  .filter(r => r.embeddable !== false)
  .map(r => ({
    ytId:          r.ytId,
    title_ar:      extractSeriesName(r.title_ar || r.title),
    title_orig:    r.title,
    origin:        (r.origin && r.origin !== 'other') ? r.origin : query.origin,
    language:      (r.language && r.language !== 'ar_dubbed') ? r.language : query.language,
    category:      r.category,
    poster_url:    r.poster_url,
    year:          r.year,
    series_id:     'series_' + r.ytId,
    episode_number: extractEpisodeNumber(r.title || ''),
    query:         query.query
  }));

console.log(`[Series] ${query.query} → ${series.length} results`);
return [{ json: { series, query: query.query } }];

const { series } = $input.first().json;
const API_URL = 'https://mawso3a-stream.vercel.app/api/import';
const SECRET = process.env.N8N_SECRET;

async function post(action, body) {
  const r = await fetch(`${API_URL}?action=${action}`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${SECRET}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  return r.json().catch(() => ({ ok: false }));
}

let imported = 0, skipped = 0;
for (const s of series) {
  try {
    await post('import-series', {
      id: s.series_id, title_ar: s.title_ar, title_orig: s.title_orig,
      origin: s.origin, language: s.language, category: s.category,
      poster_url: s.poster_url, year: s.year, total_eps: 0
    });
    const er = await post('import-episode', {
      ytId: s.ytId, series_id: s.series_id,
      title_ar: s.title_orig, season: 1, episode: s.episode_number
    });
    er.ok ? imported++ : skipped++;
  } catch(e) {
    console.error('Error importing series:', s.title_ar, e.message);
    skipped++;
  }
}

console.log(`[Series] DONE: ${imported} imported, ${skipped} skipped`);
return [{ json: { imported, skipped, run_at: new Date().toISOString() } }];
